export const singaporeMap = JSON.parse(singaporeMapJson)

export const calendarDays: { date: string; data: PieDatum[] }[] = Array.from(
  { length: 31 },
  (_, i) => {
    let seed = (i + 1) * 7919
    const next = (max: number) => {
      seed = (seed * 9301 + 49297) % 233280
      return Math.round((seed / 233280) * max)
    }
    const work = 5 + next(6)
    const play = 2 + next(5)
    return {
      date: `2024-03-${String(i + 1).padStart(2, '0')}`,
      data: [
        { label: 'Work', value: work, variant: 'primary' as const },
        { label: 'Entertainment', value: play, variant: 'info' as const },
        {
          label: 'Sleep',
          value: 24 - work - play,
          variant: 'success' as const,
        },
      ],
    }
  }
)

